{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C04","C07","C12","C19","C26","C01","C11","C18","C28","C31","C34","C35","C42"],
  "contradictory_card_ids": ["C02","C13","C29"],
  "prediction_basis_card_ids": ["C04","C07","C12","C19","C01","C11","C18"],
  "claims": [
    {
      "claim": "Human amitriptyline oral bioavailability values of 40-60% (C04), 46±48% (C07), 48±11% (C12), 47.7±11.0% (C19), and 30-60% (C26) show that a lipophilic tricyclic tertiary amine with a basic side chain can exceed the 20% F threshold.",
      "card_ids": ["C04","C07","C12","C19","C26"]
    },
    {
      "claim": "Human alfentanil oral bioavailability values of 37% (C01), 0.45±0.09 (C11), 0.42±0.15 (C18), and 41% (C28) support moderate oral bioavailability for the query's anilino-basic-amine scaffold; the single 1% table value (C13) is an outlier within that context.",
      "card_ids": ["C01","C11","C18","C28","C13"]
    },
    {
      "claim": "L3 oral exposure records for imipramine (C31) and desipramine (C34, C35, C42) show measurable systemic AUC after oral dosing in humans, consistent with meaningful oral absorption for lipophilic basic tricyclic amines similar to the query; these records do not provide absolute F but do not contradict the high prediction.",
      "card_ids": ["C31","C34","C35","C42"]
    },
    {
      "claim": "Low-F records for selegiline (C02, C03, C06, C08, C09, C14, C16, C23), rotigotine/N-0437 (C10, C17, C25, C27), and brexanolone (C20) depend on specific liabilities—propargyl/MAO metabolism, phenolic conjugation/GI mucosal metabolism, and steroid scaffold—that are absent in the query, so they do not affirmatively establish F<20% for the query.",
      "card_ids": ["C02","C03","C06","C08","C09","C14","C16","C23","C10","C17","C25","C27","C20"]
    },
    {
      "claim": "The rat amitriptyline F of 4.4% (C29) is species-specific and does not override the consistent human amitriptyline values; the query is assessed against human oral bioavailability.",
      "card_ids": ["C29"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C31","C34","C35","C42"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C32","C33","C36","C37","C38","C39","C40","C41"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule; the decision relies on transfer from analog contexts.",
    "No query-specific data on first-pass metabolism, hepatic/intestinal clearance, or efflux are available.",
    "The L3 oral AUC/Cmax records do not include IV comparators, so they cannot independently establish absolute F.",
    "The alfentanil context contains a conflicting 1% F record (C13), adding uncertainty to that analog.",
    "The query is fully ionized at physiological pH (pKa 10.02), which could reduce passive permeability, but this physicochemical prior is not endpoint proof.",
    "A rat amitriptyline F of 4.4% (C29) highlights species differences, but human amitriptyline values are consistently above threshold."
  ],
  "decision_summary": "Predicted high (F>=20%) because the query's lipophilic basic diamine/aniline scaffold is best matched by human amitriptyline (F ~30-60%) and alfentanil (F ~37-45%), while low-F analogs carry specific metabolic liabilities absent in the query. New L3 oral AUC/Cmax records for imipramine and desipramine show measurable oral exposure in similar lipophilic basic amines and are consistent with the high prediction, but they do not provide absolute F; confidence remains moderate because all evidence is transferred."
}

